def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to detect negative cycles and find shortest paths
    # Since the weight can be up to 100 and n is up to 100, 100 iterations are sufficient
    dist = [float('inf')] * n
    dist[s] = 0

    for i in range(n):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                if v == t:
                    return -1  # Negative cycle reachable from s, so no shortest path
                # If t is not reachable due to cycle, continue checking

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1

    return dist[t]
