    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with Dijkstra's algorithm for shortest path
    dist = [-1] * n
    dist[s] = 0
    q = deque()
    q.append(s)

    while q:
        u = q.popleft()
        for v, w in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + w
                q.append(v)
            else:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    q.append(v)

    return dist[t]
