def solve(n, edges):
    from collections import defaultdict

    def dijkstra(start, end, graph):
        dist = [float('inf')] * n
        dist[start] = 0
        visited = [False] * n
        heap = [(0, start)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            if u == end:
                return current_dist
            for v, w in graph[u]:
                if not visited[v] and dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    if n == 0:
        return 0

    for u in range(n):
        for v, w in graph[u]:
            if u == v:
                if w < 0:
                    return -1
                if u == v and w != 0:
                    return -1

    s = 0
    t = 1
    if s == t:
        return 0

    result = dijkstra(s, t, graph)
    return result if result != float('inf') else -1
