def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Use a deque for BFS-like processing with dynamic priority (like Dijkstra's)
    queue = deque()
    queue.append(s)

    # Keep track of visited nodes to avoid reprocessing
    visited = [False] * n

    while queue:
        u = queue.popleft()
        visited[u] = True

        for v, w in get_neighbors(u, edges):
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    queue.append(v)

    return dist[t] if dist[t] != INF else -1

def get_neighbors(u, edges):
    neighbors = []
    for edge in edges:
        if edge[0] == u:
            neighbors.append((edge[1], edge[2]))
    return neighbors
