def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to detect negative cycles and find shortest paths
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                # If there is a negative cycle that is reachable from s and can reach t, then it's unbounded
                # Check if t is reachable from this cycle
                if t in [node for node, _ in bfs_reach(u, adj)]:
                    return -1

    return dist[t] if dist[t] != float('inf') else -1

def bfs_reach(start, adj):
    visited = set()
    queue = deque([start])
    visited.add(start)
    while queue:
        node = queue.popleft()
        for neighbor, _ in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited
