```python
def count_components(n, edges):
    # Initialize parent array for Union-Find data structure
    parent = list(range(n))

    # Find root of a node
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])  # Path compression
        return parent[u]

    # Union two nodes
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u  # Union by attaching root_v to root_u

    # Process all edges
    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)
```

