import sys
sys.setrecursionlimit(10000)

def has_cycle(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    rec_stack = [False] * n

    def dfs(u):
        if not visited[u]:
            visited[u] = True
            rec_stack[u] = True
            for v in graph[u]:
                if not visited[v]:
                    if dfs(v):
                        return True
                elif rec_stack[v]:
                    return True
            rec_stack[u] = False
            return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return True
    return False
