def union(parent, rank, x, y):
    x_root = find_parent(parent, x)
    y_root = find_parent(parent, y)
    if x_root == y_root:
        return
    if rank[x_root] < rank[y_root]:
        parent[x_root] = y_root
    else:
        parent[y_root] = x_root
        if rank[x_root] == rank[y_root]:
            rank[x_root] += 1

def has_cycle(parent, rank, edges):
    for u, v in edges:
        u_root = find_parent(parent, u)
        v_root = find_parent(parent, v)
        if u_root == v_root:
            return True
        union(parent, rank, u, v)
    return False

def find_components_count(parent, n):
