    for i in range(n):
        if find_parent(parent, i) == i:
            count += 1
    return count

def solve(n, edges):
    parent = list(range(n))
    rank = [1] * n
    if has_cycle(parent, rank, edges):
        return -1
    return find_components_count(parent, n)
