def solve(n, grid):
    # Check if grid is a square matrix
    if not grid or len(grid) != n or any(len(row) != n for row in grid):
        return 0

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                current = stack.pop()
                for neighbor in range(n):
                    if grid[current][neighbor] and not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    return count
