def solve(n, edges):
    # Initialize parent array for Union-Find
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False  # Already in the same set
        parent[root_v] = root_u
        return True

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)
