class Solution:
    def solve(self, n, edges):
        # Build the graph using adjacency list
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        visited = [False] * n
        components = 0

        # DFS to traverse the graph
        def dfs(node):
            if visited[node]:
                return
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)

        # Count connected components
        for i in range(n):
            if not visited[i]:
                dfs(i)
                components += 1

        return components
