def solve(n, edges):
    # If no edges, each node is its own component
    if not edges:
        return n

    # Create a list to hold the connected components
    components = []

    # Initialize the parent array for Union-Find
    parent = list(range(n))

    # Find function with path compression
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    # Union function
    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Find all unique roots
    root_set = set()
    for i in range(n):
        root_set.add(find(i))

    # The number of unique roots is the number of connected components
    return len(root_set)
