#include <vector>
#include <list>
#include <queue>

class Solution {
public:
    std::vector<int> bfs(int n, const std::vector<std::vector<int>>& graph) {
        std::vector<bool> visited(n, false);
        std::vector<int> result;
        std::queue<int> q;

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                q.push(i);
                visited[i] = true;
                int count = 0;
                while (!q.empty()) {
                    int node = q.front();
                    q.pop();
                    ++count;
                    for (int neighbor : graph[node]) {
                        if (!visited[neighbor]) {
                            visited[neighbor] = true;
                            q.push(neighbor);
                        }
                    }
                }
                result.push_back(count);
            }
        }
        return result;
    }
};
