def shortest_path(start, end, graph):
    # Dijkstra's algorithm for shortest path in a weighted graph
    import heapq

    if start == end:
        return 0

    visited = set()
    heap = [(0, start)]  # (cost, node)
    while heap:
        cost, node = heapq.heappop(heap)
        if node == end:
