def solve(n, edges, queries):
    # Initialize adjacency list
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    import heapq

    def dijkstra(start, end):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        heap = [(0, start)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == end:
                return current_dist
            if current_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Process each query
    results = []
    for s, t in queries:
        shortest_distance = dijkstra(s, t)
        results.append(shortest_distance)

    return results
