import heapq

def dijkstra_with_restricted_terms(graph, start):
    """Find the shortest path from the start node to all other nodes using Dijkstra's algorithm."""
    if start not in graph:
        return {}

    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return dist

def solve(graph, start, end):
    """Solve the shortest path problem in a weighted directed graph."""
    if start == end:
        return 0

    if start not in graph or end not in graph:
        return -1

    shortest_distances = dijkstra_with_restricted_terms(graph, start)
    if shortest_distances[end] == float('inf'):
        return -1

    return shortest_distances[end]
