def solve(n, edges):
    def add_edge(u, v):
        graph[u].append(v)
        graph[v].append(u)

    graph = [[] for _ in range(n)]
    for u, v in edges:
        add_edge(u, v)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    return count
```

